public static void main(String[] args){
    Scanner scan = new Scanner(System.in);
    ArrayList<Integer> list = new ArrayList<Integer>();

    int N = scan.nextInt();
    int L = scan.nextInt() - 1;
    int R = scan.nextInt() - 1;

    for(int i = 0 ; i < N ; i++){
        list.add(i + 1);
    }

    while(L <= R){
        int comL = list.get(L);    //左を一時格納
        int comR = list.get(R);    //右を一時格納
        list.set(L, comR);
        list.set(R, comL);
        L++;
        R--;
    }

    for(int i = 0 ; i < N ; i++){
        System.out.print(list.get(i));
        if (i < N - 1) {
            System.out.print(" ");
        }
    }

    scan.close();
}
